import csv
import io
import re
from typing import List, Dict


def parse_csv(raw_csv: str):
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(
        io.StringIO(text, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    for record in reader:
        if record and any(value.strip() for value in record):
            records.append([str(value) for value in record])

    if not records:
        return {"columns": [], "rows": []}

    expected_width = 9
    header_index = None
    for index, record in enumerate(records):
        if len(record) == expected_width:
            textual_fields = sum(
                bool(re.search(r"[A-Za-z]", value)) for value in record
            )
            if textual_fields >= 2:
                header_index = index
                break

    if header_index is None:
        header_index = 0

    columns = records[header_index][:]
    data_records = records[header_index + 1:]
    width = max(len(columns), max((len(row) for row in data_records), default=0))

    if width > len(columns):
        columns.extend("Extra_{}".format(index) for index in range(1, width - len(columns) + 1))

    rows = []
    for record in data_records:
        if len(record) > len(columns):
            record = record[:len(columns) - 1] + [",".join(record[len(columns) - 1:])]
        rows.append(record + [""] * (len(columns) - len(record)))

    return {"columns": columns, "rows": rows}
